EXTRAS = [
dict(n=81, gr='will', vb='help,wash,carry,promise,offer',
 c1="Will ou shall?|'Will' serve para decisões na hora, promessas e previsões. 'Shall I…?' é uma oferta educada, típica do inglês britânico: 'Shall I open the window?'. Nos EUA, use 'Should I…?'.",
 c2="Promessas|Em inglês, 'a promise is a promise' (promessa é promessa). Quando alguém diz 'I promise', espera-se que cumpra. Cruzar os dedos às costas significa que a promessa não vale!",
 ar=("A helpful neighbor","On Maple Street, Bruno is famous for his help. When Pru has too many dishes, he says, \"I'll wash them.\" When Naomi has heavy bags, he says, \"I'll carry them.\" When Mia needs a ladder, he says, \"I'll bring mine.\" He always says, \"I promise I won't be late.\" And he never is. One day Pru asks, \"Why do you always help?\" Bruno answers, \"Because one day I'll need help, too. And I know this street will help me.\" Pru smiles. \"We will.\"","Bruno é conhecido por oferecer ajuda e cumprir promessas.","O que Bruno oferece a Naomi?=To carry her bags|To wash dishes|To cook;;Bruno chega atrasado?=Never|Always|Often"),
 ex="I'll be there.=Estarei lá.~Promessa|Leave it to me.=Deixe comigo.~Oferta|I'll give you a hand.=Dou uma mão.~Oferta|You have my word.=Dou a minha palavra.~Promessa|Don't worry, I've got it.=Não se preocupe, eu cuido.~Oferta",
 tf="I'll é a forma curta de I will.=T|Won't é a forma negativa de will.=T|Bruno nunca ajuda.=F|Bruno traz uma escada.=T",
 odd="help,wash,carry,table=table|will,won't,shall,bread=bread"),
dict(n=82, gr='will', vb='predict,live,travel,change,hope',
 c1="Prever o futuro|Para previsões gerais, use 'will': 'It will rain.' Para possibilidade, use 'might' ou 'may': 'It might rain.' 'Probably' reforça: 'It'll probably rain.'",
 c2="O futuro do mundo|Cientistas dizem que, em 2050, haverá carros elétricos, casas inteligentes e talvez turismo espacial. Em inglês, 'AI' (Artificial Intelligence) é a inteligência artificial. 'Self-driving cars' são carros autônomos.",
 ar=("Under the stars","Ryo and Una lie on the grass and look at the stars. They talk about the future. Ryo thinks that cities will be greener and cars will be electric. \"Robots will help us at home,\" he says. Una thinks that people might live on other planets. \"We might even have vacations on the moon,\" she says. Ryo laughs. \"Who knows?\" They agree that the most important thing in the future will be kindness. A shooting star crosses the sky. They both make a wish.","Os amigos imaginam o futuro sob as estrelas.","O que Ryo acha das cidades?=They will be greener|They will be bigger|They will disappear;;O que é mais importante no futuro?=Kindness|Money|Speed"),
 ex="Time will tell.=O tempo dirá.~Incerteza|Only time will tell.=Só o tempo dirá.~Incerteza|The future is bright.=O futuro é brilhante.~Otimismo|Who knows?=Quem sabe?~Incerteza|Fingers crossed!=Dedos cruzados!~Torcida",
 tf="Will faz previsões.=T|Might expressa possibilidade menor.=T|Una acha que ninguém viverá em outros planetas.=F|Ryo fala de cidades mais verdes.=T",
 odd="robot,planet,future,spoon=spoon|will,might,may,yesterday=yesterday"),
dict(n=83, gr='haveto', vb='work,wear,clean,arrive,pay',
 c1="Must ou have to?|'Must' vem de dentro ou de uma regra forte; 'have to' vem de fora (obrigação externa). 'I have to wake up early' (meu trabalho exige). 'Don't have to' = não precisa, ≠ mustn't = proibido.",
 c2="Segurança no trabalho|Em oficinas e canteiros de obra, o 'hard hat' (capacete) e os 'safety glasses' (óculos de proteção) são obrigatórios. Em inglês, 'safety rules' são regras de segurança e 'PPE' é equipamento de proteção.",
 ar=("First day at the workshop","Zoe starts working at Jack's workshop. \"What do I have to do?\" she asks. Jack says, \"You have to arrive at eight and wear a helmet and safety glasses. You don't have to bring tools: the shop has everything. You have to clean your workbench at five.\" Zoe takes notes. \"Do I have to work on Saturday?\" \"No, you don't. It's your day off.\" Zoe smiles. She likes the rules because they are clear and fair. By the end of the day, she feels like part of the team.","Zoe aprende o que é obrigatório e o que não é na oficina de Jack.","A que horas Zoe chega?=Eight|Nine|Seven;;Ela trabalha no sábado?=No|Yes|Sometimes"),
 ex="It's a must.=É obrigatório.~Regra|I'm required to…=Sou obrigado a…~Regra|You're not allowed to…=Você não tem permissão para…~Proibição|It's up to you.=Depende de você.~Escolha|Rules are rules.=Regras são regras.~Regra",
 tf="Have to expressa obrigação.=T|Don't have to expressa proibição.=F|Zoe não tem que trazer ferramentas.=T|O sábado é dia de folga.=T",
 odd="helmet,glasses,tools,pizza=pizza|have to,must,don't have to,table=table"),
dict(n=84, gr='should', vb='sleep,exercise,rest,drink,walk',
 c1="Dar conselhos|'Should' é o jeito mais comum de aconselhar. Para suavizar: 'Why don't you…?' ou 'You might want to…'. 'If I were you, I'd…' também é muito usado.",
 c2="Estresse|Em inglês, 'stress' é estresse e 'to relax' é relaxar. Atividades que ajudam: 'take a walk' (caminhar), 'meditate' (meditar) e 'get enough sleep' (dormir o suficiente).",
 ar=("A walk in the park","Oscar works too much. He sleeps five hours a night and drinks seven coffees a day. \"I'm very stressed,\" he tells Naomi. Naomi gives him advice: \"You should sleep more, walk every day and drink less coffee.\" Oscar tries it. After two weeks, he feels different. He sleeps eight hours, walks for thirty minutes and drinks two coffees. He smiles more and works better. He tells Naomi, \"Your advice changed my life.\" Naomi says, \"It was your decision to follow it.\"","Os conselhos de Naomi mudam a rotina e o humor de Oscar.","Quantos cafés Oscar bebia?=Seven|Two|Ten;;Como Oscar está depois?=Better|Worse|The same"),
 ex="If I were you, I'd…=Se eu fosse você, eu…~Conselho|Take it easy.=Vá com calma.~Conselho|Why don't you…?=Por que você não…?~Sugestão|Get some rest.=Descanse um pouco.~Conselho|Sleep on it.=Pense com calma.~Decisão",
 tf="Should dá conselho.=T|Shouldn't é não deveria.=T|Oscar dorme oito horas no começo.=F|Oscar segue os conselhos.=T",
 odd="sleep,exercise,rest,stress=stress|should,shouldn't,must,table=table"),
dict(n=85, gr='perfect', vb='be,see,eat,fly,meet',
 c1="Have you ever…?|Para falar de experiências de vida sem data, use o present perfect: 'Have you ever been to Japan?'. Resposta curta: 'Yes, I have' / 'No, I haven't'. 'Never' significa nunca.",
 c2="Been ou gone?|'I've been to Paris' = fui e voltei. 'I've gone to Paris' = foi e ainda está lá. Pequena diferença, grande confusão! Em experiências de vida, prefira 'been'.",
 ar=("Life experiences","At the airport, Tessa and Noah wait for their flights. Noah has traveled to ten countries. He has eaten sushi in Japan, climbed a mountain in Peru and swum in the Red Sea. \"Have you ever been abroad?\" he asks Tessa. \"No, I haven't,\" she says. \"I've never left my country.\" \"You should try it!\" says Noah. \"One day I will,\" says Tessa. She looks at the planes and smiles. \"Maybe my first trip starts today.\" Noah smiles: \"I hope so.\"","Noah tem muitas experiências de viagem; Tessa sonha em ter as suas.","Quantos países Noah visitou?=Ten|Two|Twenty;;O que Tessa nunca fez?=Left her country|Eaten pizza|Watched TV"),
 ex="Have you ever…?=Você já…?~Experiência|I've never been there.=Nunca fui lá.~Experiência|It's a first for me.=É a primeira vez.~Novidade|Been there, done that.=Já passei por isso.~Experiência|Never say never.=Nunca diga nunca.~Provérbio",
 tf="Have you ever…? fala de experiências.=T|Been é particípio de be.=T|Tessa já viajou ao exterior.=F|Noah visitou o Japão.=T",
 odd="been,seen,eaten,go=go|ever,never,already,table=table"),
dict(n=86, gr='perfect', vb='finish,start,study,leave,arrive',
 c1="Just, already e yet|'Just' = acabou de. 'Already' = já (afirmativa). 'Yet' = ainda (negativa e pergunta, no fim). 'I've just finished', 'I've already eaten', 'Have you eaten yet?'.",
 c2="Estudar para provas|Dicas de estudo em inglês: 'make a study plan' (faça um plano), 'review your notes' (revise suas anotações), 'take practice tests' (faça simulados), 'get a good night's sleep' (durma bem).",
 ar=("Before the test","The exam is tomorrow. Greta has already studied the vocabulary and has just finished the reading. She hasn't studied the grammar yet. \"Have you finished your homework?\" asks Mia. \"Not yet,\" says Greta, \"but I'm almost done.\" Tonight she will study the grammar with a cup of tea and some music. She feels nervous but ready. Mia says, \"You've worked hard. You'll do well.\" Greta smiles. She has already learned a lot, and she knows it.","Greta se prepara para a prova: já estudou parte, falta gramática.","O que Greta acabou de terminar?=The reading|The grammar|The vocabulary;;Quando é a prova?=Tomorrow|Today|Next week"),
 ex="I'm all done.=Terminei tudo.~Finalizar|Not yet.=Ainda não.~Resposta|Just in time!=Em cima da hora!~Prazo|I've got this.=Eu consigo.~Confiança|Good luck!=Boa sorte!~Prova",
 tf="Already é usado em afirmativas.=T|Yet é usado no fim de negativas.=T|Greta já estudou toda a gramática.=F|A prova é amanhã.=T",
 odd="already,yet,just,table=table|finished,started,studied,go=go"),
dict(n=87, gr='somany', vb='need,buy,bring,ask,share',
 c1="Much ou many?|Many para contáveis (many chairs); much para incontáveis (much water). 'A lot of' serve para os dois e é natural em frases afirmativas. 'Too much / too many' = demais.",
 c2="Churrasco ao redor do mundo|Os americanos adoram 'barbecue' ou 'BBQ'. Em inglês, 'to grill' é grelhar, 'burgers' e 'hot dogs' são clássicos. O Dia da Independência (4 de julho) é o dia mais churrasqueiro do ano.",
 ar=("Barbecue planning","Beto and Rita organize a barbecue for twenty people. \"How much meat do we need?\" asks Rita. \"A lot of it,\" says Beto. \"Maybe ten kilos.\" \"And how many chairs do we have?\" \"Not many. Only eight.\" Rita says, \"I'll ask the neighbors for a few more.\" At the supermarket they buy ten kilos of meat, a lot of bread and some fruit. At home they discover there isn't much ice, so they buy some more. By evening, everything is ready and the first guests arrive.","Beto e Rita organizam um churrasco e pedem cadeiras emprestadas.","Quantos quilos de carne compram?=Ten|Five|Twenty;;O que falta?=Ice|Meat|Bread"),
 ex="A bit of…=Um pouco de…~Quantidade|Plenty of…=Muito(s)…~Quantidade|I've got loads of…=Tenho um monte de…~Informal|Not enough=Não o suficiente~Quantidade|More than enough=Mais que suficiente~Quantidade",
 tf="Many é usado com contáveis.=T|Much é usado com incontáveis.=T|Ice é contável.=F|Beto e Rita compram carne.=T",
 odd="chairs,friends,apples,water=water|much,many,a lot of,table=table"),
dict(n=88, gr='prep', vb='put,sit,stand,find,hide',
 c1="In, on, at|Pense assim: AT é um ponto exato (at the door, at nine), ON é uma superfície ou dia (on the table, on Monday), IN é um espaço ou período (in the box, in May).",
 c2="Preposições que pegam|'In the morning' mas 'at night'. 'On Monday' mas 'at the weekend' (UK) ou 'on the weekend' (EUA). As preposições em inglês seguem hábitos, não regras lógicas. Aprenda em frases.",
 ar=("Where is everything?","Theo's desk is in the corner of the room. The schedule is on the desk, next to the lamp. The keys are in his bag, behind the books. The photos are on the wall, above the sofa. The cat is under the table. The meeting is on Tuesday at ten o'clock. The party is in December. Ida likes to have everything in its place. \"Where is my pen?\" she asks. \"It's behind your ear!\" says Theo. They laugh. Order is good, but a little chaos is fun.","Tudo tem seu lugar e horário na rotina de Theo e Ida.","Onde está o abajur?=Next to the schedule|In the bag|Under the desk;;Quando é a festa?=In December|In May|On Tuesday"),
 ex="In the nick of time=Em cima da hora~Idiom|On the other hand=Por outro lado~Contraste|At the end of the day=No fim das contas~Conclusão|In a nutshell=Resumindo~Resumo|On top of that=Além disso~Adição",
 tf="On Monday está correto.=T|In 9 o'clock está correto.=F|Under é embaixo de.=T|The keys are in the bag.=T",
 odd="in,on,at,table=table|under,behind,above,Monday=Monday"),
dict(n=89, gr='phrasal', vb='turn,look,put,pick,sit',
 c1="Verbo + partícula|Phrasal verbs são combinações como look up (procurar), give up (desistir), turn on (ligar). Alguns são separáveis: 'turn the light on' ou 'turn on the light'. Outros, não: 'look after a baby'.",
 c2="Fala natural|Falantes nativos usam phrasal verbs o tempo todo, principalmente em conversas. Em vez de 'enter', dizem 'come in'. Em vez de 'continue', 'keep going'. Aprender 30 phrasal verbs muda sua fluência.",
 ar=("Morning chaos","Gigi gets up late. She looks for her keys, puts on her coat and turns off the lights. She picks up her bag and runs to the bus stop. The bus is full, so she stands up all the way. At work she sits down, takes off her coat and turns on her laptop. \"What a morning!\" she says. Her colleague laughs. \"You look tired. Why don't you take a break?\" Gigi smiles. \"Tomorrow I'll get up earlier and have a calm morning.\" Her colleague says, \"I'll believe it when I see it!\"","Gigi acorda atrasada e corre, usando vários phrasal verbs.","O que Gigi procura?=Her keys|Her bag|Her phone;;O que faz no trabalho?=Sits down|Runs|Sleeps"),
 ex="Look out!=Cuidado!~Alerta|Give it a try.=Dê uma chance.~Incentivo|Hang in there!=Aguente firme!~Incentivo|Figure it out.=Descubra.~Resolver|Hang on a second.=Espere um segundo.~Pausa",
 tf="Turn on é ligar.=T|Look for é olhar.=F|Put on é vestir.=T|Take off é tirar.=T",
 odd="turn on,turn off,put on,table=table|get up,sit down,come in,hat=hat"),
dict(n=90, gr='should', vb='promise,advise,try,experience,decide',
 c1="Revisão ativa|Para fixar, misture temas: faça uma promessa (I'll…), dê um conselho (You should…), fale de uma experiência (I've been…). Frases mistas mostram domínio.",
 c2="Trivia nights|Em pubs ingleses há 'trivia nights': equipes respondem perguntas de cultura geral. Quem vence ganha uma rodada de bebidas! É um bom jeito de praticar inglês e conhecer pessoas.",
 ar=("The big quiz","At the review quiz, the neighbors are in two teams. They answer questions about advice, experiences, plans and quantities. \"What should you do if you're tired?\" asks Mia. \"You should rest and sleep more,\" answers Team A. \"Have you ever been abroad?\" asks Naomi. \"Yes, I have!\" answers Team B. The score is very close. In the final question, both teams give the same answer. Mia declares a tie. \"You all won!\" she says, and everybody gets a cookie. They laugh and eat together.","O quiz de revisão termina em empate e todos ganham biscoitos.","Como termina o quiz?=A tie|Team A wins|Team B wins;;O que todos ganham?=A cookie|A medal|A book"),
 ex="It's a tie.=É empate.~Jogo|Great minds think alike.=Grandes mentes pensam igual.~Concordância|You nailed it!=Você acertou em cheio!~Elogio|Keep it up!=Continue assim!~Incentivo|Well done!=Muito bem!~Elogio",
 tf="Um quiz pode terminar em empate.=T|A equipe A ganha o quiz.=F|Todos ganham biscoitos.=T|Naomi é a professora.=F",
 odd="quiz,team,score,table=table|should,have to,will,pizza=pizza"),
]
